            for dt_key, dt_val in raw_dates.items():
                if isinstance(dt_val, dict):
                    raw_status = dt_val.get("status", "available")
                    if raw_status not in _VALID_STATUSES:
                        dt_val["status"] = _STATUS_MAP.get(raw_status, "available")
                    for fld in ("prices", "available_seats"):
                        if fld in dt_val and isinstance(dt_val[fld], dict):
                            dt_val[fld] = {k: v for k, v in dt_val[fld].items() if k in _VALID_CABS}
                clean_dates[dt_key] = dt_val
            flights[r["flight_id"]] = {
                "flight_number": r["flight_id"],
                "origin": r["origin"],
                "destination": r["destination"],
                "scheduled_departure_time_est": r["departure_time"] or "00:00:00",
                "scheduled_arrival_time_est": r["arrival_time"] or "00:00:00",
                "dates": clean_dates,
            }
        resv_by_user = {}
        reservations = {}
        for r in conn.execute("SELECT * FROM flight_bookings WHERE source_skill=?", (SOURCE_SKILL,)):
            res_flights = []
            for fj in json.loads(r["flights_json"] or "[]"):
                res_flights.append({
                    "flight_number": fj.get("flight_number") or fj.get("flight_id"),
                    "origin": fj.get("origin", ""),
                    "destination": fj.get("destination", ""),
                    "date": fj.get("date", ""),
                    "price": fj.get("price", 0),
                })
            raw_passengers = json.loads(r["passengers_json"] or "[]")
            clean_passengers = [_normalize_passenger(p) for p in raw_passengers]
            reservations[r["booking_id"]] = {
                "reservation_id": r["booking_id"],
                "user_id": r["user_id"],
                "origin": r["origin"],
                "destination": r["destination"],
                "flight_type": r["flight_type"] if r["flight_type"] in _TAU2_FLIGHT_TYPES else "one_way",
                "cabin": r["cabin_class"] if r["cabin_class"] in _TAU2_CABINS else "economy",
                "flights": res_flights,
